using System.Reflection; using Grasshopper;
foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){ Type[] ts; try{ ts=a.GetTypes(); }catch(ReflectionTypeLoadException e){ ts=e.Types.Where(t=>t!=null).ToArray(); } catch{ continue; }
 foreach(var t in ts.Where(t=>t.Name=="GH_Model"||t.Name=="Param_Model")) Console.WriteLine(t.FullName+" in "+a.GetName().Name+" ctors: "+string.Join(" | ",t.GetConstructors().Select(c=>string.Join(",",c.GetParameters().Select(p=>p.ParameterType.FullName))))); }
foreach(var n in new[]{"Beam Forces","Utilization of Elements","Buckling Modes","Reaction Forces","Analyze","Nodal Displacements","Assemble Model"}) foreach(var q in Instances.ComponentServer.ObjectProxies.Where(x=>x.Desc.Name==n && !x.Obsolete)){ var o=q.CreateInstance() as Grasshopper.Kernel.IGH_Component; if(o==null) continue; Console.WriteLine("## "+n+" ("+q.Desc.Category+") IN "+string.Join(", ",o.Params.Input.Select(i=>i.Name+":"+i.TypeName))+" OUT "+string.Join(", ",o.Params.Output.Select(i=>i.Name+":"+i.TypeName))); }
